import { type TeamHuntState } from "@hunt/public-client";
import {
  ConditionalTooltip,
  FilterButton,
  PrimarySearchField,
} from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import { SearchIcon } from "lucide-react";
import React, { useCallback, useEffect, useMemo, useState } from "react";
import type { AllPuzzlesState } from "../client/all_puzzles_types";
import type {
  ResearchTasksTask,
  ResearchTasksState,
} from "../client/research_tasks_types";
import PuzzleCard, {
  PuzzleIconFromState,
} from "./PuzzleAndTaskDisplay/PuzzleCard";
import { RoundFolder } from "./PuzzleAndTaskDisplay/RoundFolder";
import { TaskSubmissionIcon } from "./PuzzleAndTaskDisplay/TaskSubmissionIcon";
import {
  type Style,
  useFolderHeights,
} from "./PuzzleAndTaskDisplay/useFolderHeights";
import { TeamStateProvider } from "./TeamStateProvider";

const LOCAL_STORAGE_KEYS = {
  showUnlocked: "research-tasks-show-unlocked",
  showInReview: "research-tasks-show-in-review",
  showSolved: "research-tasks-show-solved",
  showAuto: "research-tasks-show-auto",
  showManual: "research-tasks-show-manual",
  showGameworld: "research-tasks-show-gameworld",
  showEvent: "research-tasks-show-event",
};

const TasksListForRound = ({ tasks }: { tasks: ResearchTasksTask[] }) => {
  return (
    <div className="w-full px-3 pb-3 flex flex-col gap-3">
      {tasks.map((task) => {
        return (
          <React.Fragment key={task.slug}>
            <PuzzleCard
              lockState={task.state ?? "locked"}
              title={task.title}
              slug={task.slug}
              desc={task.desc}
              solved={task.solved}
              prize={task.prize}
              prizeMax={task.prizeMax}
              is_overworld_feeder={false}
              submissionType={task.submissionType}
              taskSubmissionState={task.taskSubmissionState}
            />
          </React.Fragment>
        );
      })}
    </div>
  );
};

type ResearchTasksRound = {
  slug: string;
  title: string;
  tasks: ResearchTasksTask[];
};

type ResearchTasksRoundProps = {
  round: ResearchTasksRound;
  index: number;
  getStyle: () => Style;
  state: ResearchTasksState;
  allTasksVisible: boolean;
  search: string;
  teamState: TeamHuntState;
};

const ResearchTasksRound = ({
  round,
  index,
  getStyle,
  state,
  allTasksVisible,
  search,
  teamState,
}: ResearchTasksRoundProps) => {
  const count = round.tasks.length;
  const isUnlocked = teamState.rounds[round.slug]?.locked === "unlocked";
  const roundLink =
    round.slug === "kingdom_of_the_puzzmon" ? "/" : `/rounds/${round.slug}`;

  if (
    count === 0 &&
    // Do not show empty folders when we are filtering.
    (!allTasksVisible ||
      // However, we do want to show the empty folder if the search term directly matches the round title.
      !round.title.toLowerCase().includes(search.trim().toLowerCase()))
  ) {
    return null;
  }

  // Create a compatible structure for RoundFolder
  const roundForFolder = {
    slug: round.slug,
    title: round.title,
    puzzles: [], // Empty array since we're using tasks
    is_overworld_round: false,
  };

  // Create a minimal compatible state structure for RoundFolder
  const compatibleState: AllPuzzlesState = {
    epoch: state.epoch,
    rounds: [],
    currency: state.currency,
  };

  return (
    <RoundFolder
      round={roundForFolder}
      index={index}
      count={count}
      getStyle={getStyle}
      state={compatibleState}
      href={isUnlocked ? roundLink : undefined}
    >
      {round.tasks.length > 0 ? (
        <TasksListForRound tasks={round.tasks} />
      ) : (
        <div className="text-xl text-secondary font-semibold px-6 pb-4">
          {isUnlocked ? (
            <>
              Explore{" "}
              <a
                href={roundLink}
                className="underline text-secondary hover:text-accent-blue"
              >
                {round.title}
              </a>{" "}
              to discover tasks!
            </>
          ) : (
            <>Unlock {round.title} to discover tasks!</>
          )}
        </div>
      )}
    </RoundFolder>
  );
};

type CircleFilterButtonProps = {
  selected: boolean;
  onClick: () => void;
  srLabel: string;
  icon: React.ReactNode;
  tooltip?: React.ReactNode;
  className?: string;
  tooltipClassName?: string;
  disabled?: boolean;
};

const CircleFilterButton = ({
  selected,
  onClick,
  srLabel,
  icon,
  tooltip,
  className,
  tooltipClassName,
  disabled,
}: CircleFilterButtonProps) => {
  const button = (
    <button
      type="button"
      onClick={onClick}
      aria-pressed={selected}
      className={cn(
        "group/task-submission-filter flex h-12 w-12 shrink-0 items-center justify-center rounded-full border-2 transition-colors",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        !disabled && "hover:border-accent",
        selected
          ? "bg-secondary border-secondary"
          : "bg-[#153A62]/55 border-secondary hover:bg-[#153A62]/65 focus-visible:bg-[#153A62]/65",
        className,
      )}
    >
      <span className="sr-only">{srLabel}</span>
      {icon}
    </button>
  );
  return (
    <ConditionalTooltip className={tooltipClassName} tooltip={tooltip}>
      {button}
    </ConditionalTooltip>
  );
};

export default function ResearchTasksList({
  state,
  teamState,
}: {
  state: ResearchTasksState;
  teamState: TeamHuntState;
}) {
  const [showUnlocked, setShowUnlocked] = useState<boolean>(false);
  const [showInReview, setShowInReview] = useState<boolean>(false);
  const [showSolved, setShowSolved] = useState<boolean>(false);
  const [showAutoTasks, setShowAutoTasks] = useState<boolean>(false);
  const [showManualTasks, setShowManualTasks] = useState<boolean>(false);
  const [showGameworldTasks, setShowGameworldTasks] = useState<boolean>(false);
  const [showEventTasks, setShowEventTasks] = useState<boolean>(false);
  const [search, setSearch] = useState("");

  useEffect(() => {
    setShowUnlocked(
      localStorage.getItem(LOCAL_STORAGE_KEYS.showUnlocked) === "true",
    );
    setShowInReview(
      localStorage.getItem(LOCAL_STORAGE_KEYS.showInReview) === "true",
    );
    setShowSolved(
      localStorage.getItem(LOCAL_STORAGE_KEYS.showSolved) === "true",
    );
    setShowAutoTasks(
      localStorage.getItem(LOCAL_STORAGE_KEYS.showAuto) === "true",
    );
    setShowManualTasks(
      localStorage.getItem(LOCAL_STORAGE_KEYS.showManual) === "true",
    );
    setShowGameworldTasks(
      localStorage.getItem(LOCAL_STORAGE_KEYS.showGameworld) === "true",
    );
    setShowEventTasks(
      localStorage.getItem(LOCAL_STORAGE_KEYS.showEvent) === "true",
    );
  }, []);

  useEffect(() => {
    localStorage.setItem(
      LOCAL_STORAGE_KEYS.showUnlocked,
      JSON.stringify(showUnlocked),
    );
  }, [showUnlocked]);

  useEffect(() => {
    localStorage.setItem(
      LOCAL_STORAGE_KEYS.showInReview,
      JSON.stringify(showInReview),
    );
  }, [showInReview]);

  useEffect(() => {
    localStorage.setItem(
      LOCAL_STORAGE_KEYS.showSolved,
      JSON.stringify(showSolved),
    );
  }, [showSolved]);
  useEffect(() => {
    localStorage.setItem(
      LOCAL_STORAGE_KEYS.showAuto,
      JSON.stringify(showAutoTasks),
    );
  }, [showAutoTasks]);
  useEffect(() => {
    localStorage.setItem(
      LOCAL_STORAGE_KEYS.showManual,
      JSON.stringify(showManualTasks),
    );
  }, [showManualTasks]);
  useEffect(() => {
    localStorage.setItem(
      LOCAL_STORAGE_KEYS.showGameworld,
      JSON.stringify(showGameworldTasks),
    );
  }, [showGameworldTasks]);
  useEffect(() => {
    localStorage.setItem(
      LOCAL_STORAGE_KEYS.showEvent,
      JSON.stringify(showEventTasks),
    );
  }, [showEventTasks]);

  const toggleShowUnlocked = useCallback(() => {
    setShowUnlocked((prevState) => !prevState);
  }, []);
  const toggleShowInReview = useCallback(() => {
    setShowInReview((prevState) => !prevState);
  }, []);
  const toggleShowSolved = useCallback(() => {
    setShowSolved((prevState) => !prevState);
  }, []);
  const toggleShowAutoTasks = useCallback(() => {
    setShowAutoTasks((prevState) => !prevState);
  }, []);
  const toggleShowManualTasks = useCallback(() => {
    setShowManualTasks((prevState) => !prevState);
  }, []);
  const toggleShowGameworldTasks = useCallback(() => {
    setShowGameworldTasks((prevState) => !prevState);
  }, []);
  const toggleShowEventTasks = useCallback(() => {
    setShowEventTasks((prevState) => !prevState);
  }, []);

  const filterTask = useCallback(
    (task: ResearchTasksTask) => {
      const q = search.trim().toLowerCase();

      // Text match: task title OR round title
      if (q !== "") {
        const inTask = task.title.toLowerCase().includes(q);
        const roundLabel = (
          task.roundTitle ??
          task.roundSlug ??
          ""
        ).toLowerCase();
        if (!inTask && !roundLabel.includes(q)) return false;
      }

      const submissionTypeActive =
        showAutoTasks ||
        showManualTasks ||
        showGameworldTasks ||
        showEventTasks;
      if (submissionTypeActive) {
        const allowedTypes = new Set<string>();
        if (showAutoTasks) allowedTypes.add("auto");
        if (showManualTasks) allowedTypes.add("manual");
        if (showGameworldTasks) allowedTypes.add("gameworld");
        if (showEventTasks) allowedTypes.add("event");
        if (!task.submissionType || !allowedTypes.has(task.submissionType)) {
          return false;
        }
      }

      const statusActive = showSolved || showInReview || showUnlocked;
      if (statusActive) {
        if (task.solved) {
          return showSolved;
        }
        if (task.taskSubmissionState === "pending_grade") {
          return showInReview;
        }
        if (task.state === "unlocked") {
          return showUnlocked;
        }
      }
      return true;
    },
    [
      search,
      showSolved,
      showInReview,
      showUnlocked,
      showAutoTasks,
      showManualTasks,
      showGameworldTasks,
      showEventTasks,
    ],
  );

  // Group tasks by round
  const tasksByRound = useMemo(() => {
    const grouped = new Map<string, ResearchTasksTask[]>();
    const roundOrder = new Map<string, number>();
    Object.keys(teamState.rounds).forEach((slug, idx) => {
      roundOrder.set(slug, idx);
    });

    state.tasks.forEach((task) => {
      const key = task.roundSlug ?? "ungrouped";
      if (!grouped.has(key)) {
        grouped.set(key, []);
      }
      const tasksArray = grouped.get(key);
      if (tasksArray) {
        tasksArray.push(task);
      }
    });

    return Array.from(grouped.entries())
      .sort(([aSlug], [bSlug]) => {
        const aOrder = roundOrder.get(aSlug);
        const bOrder = roundOrder.get(bSlug);
        if (aOrder !== undefined && bOrder !== undefined) {
          return aOrder - bOrder;
        }
        if (aOrder !== undefined) return -1;
        if (bOrder !== undefined) return 1;
        return aSlug.localeCompare(bSlug);
      })
      .map(([roundSlug, tasks]) => {
        const roundTitle = tasks[0]?.roundTitle ?? roundSlug;
        return {
          slug: roundSlug,
          title: roundTitle,
          tasks: tasks.sort((a, b) => {
            // Primary sort: unsolved tasks first
            if (a.solved !== b.solved) {
              return Number(a.solved) - Number(b.solved);
            }
            // Secondary sort: alphabetical by title
            return a.title.localeCompare(b.title);
          }),
        };
      });
  }, [state.tasks, teamState.rounds]);

  const filteredState = useMemo(() => {
    // Filter tasks within each round
    const filteredRounds = tasksByRound.map((round) => {
      const filteredTasks = round.tasks.filter((t) => filterTask(t));
      return { ...round, tasks: filteredTasks };
    });

    return filteredRounds.filter((round) => round.tasks.length > 0);
  }, [tasksByRound, filterTask]);

  const { getStyle } = useFolderHeights(
    filteredState.map((round) => ({ rows: round.tasks.length })),
  );

  const allTasksVisible =
    (showUnlocked && showInReview && showSolved) ||
    (!showUnlocked && !showInReview && !showSolved);

  return (
    <TeamStateProvider teamState={teamState}>
      <div className="flex flex-col gap-5">
        {/* Search + Filters */}
        <div className="flex flex-col gap-2">
          <PrimarySearchField
            name="search-all-puzzles"
            value={search}
            onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
              setSearch(e.target.value);
            }}
            placeholder="Search tasks by title or round…"
            aria-label="Search tasks by title or round"
            leftIcon={SearchIcon}
          />
          <div className="flex flex-wrap items-center gap-2">
            <FilterButton
              selected={showUnlocked}
              onClick={toggleShowUnlocked}
              icon={
                <PuzzleIconFromState
                  state="unlocked"
                  className={cn(
                    showUnlocked
                      ? "text-accent stroke-accent"
                      : "stroke-gray-400 group-hover/filter-button:stroke-white group-focus-visible/filter-button:stroke-white",
                  )}
                  isResearchTask
                />
              }
              className={cn(
                "flex-1 min-w-[10rem] justify-center",
                !showUnlocked && "text-gray-400",
              )}
            >
              UNLOCKED
            </FilterButton>
            <FilterButton
              selected={showInReview}
              onClick={toggleShowInReview}
              icon={
                <PuzzleIconFromState
                  state="pending_grade"
                  className={cn(
                    showInReview
                      ? "text-red-500"
                      : "text-gray-400 group-hover/filter-button:text-white group-focus-visible/filter-button:text-white",
                  )}
                />
              }
              className={cn(
                "flex-1 min-w-[10rem] justify-center",
                !showInReview && "text-gray-400",
              )}
            >
              IN REVIEW
            </FilterButton>
            <FilterButton
              selected={showSolved}
              onClick={toggleShowSolved}
              icon={
                <PuzzleIconFromState
                  state="solved"
                  isResearchTask
                  className={cn(
                    !showSolved &&
                      "text-gray-400 group-hover/filter-button:text-white group-focus-visible/filter-button:text-white",
                  )}
                />
              }
              className={cn(
                "flex-1 min-w-[10rem] justify-center mr-4",
                !showSolved && "text-gray-400",
              )}
            >
              COMPLETED
            </FilterButton>
            <CircleFilterButton
              selected={showAutoTasks}
              onClick={toggleShowAutoTasks}
              srLabel="Automated tasks"
              disabled={!showAutoTasks}
              icon={
                <TaskSubmissionIcon
                  submissionType="auto"
                  size="md"
                  disabled={!showAutoTasks}
                />
              }
              className="w-12"
              tooltip="Instant feedback & RP"
              tooltipClassName="bg-neutral-300 text-black border-2 border-accent-blue rounded-md"
            />
            <CircleFilterButton
              selected={showManualTasks}
              onClick={toggleShowManualTasks}
              srLabel="Manual tasks"
              disabled={!showManualTasks}
              icon={
                <TaskSubmissionIcon
                  submissionType="manual"
                  size="md"
                  disabled={!showManualTasks}
                />
              }
              className="w-12"
              tooltip="Will require staff review"
              tooltipClassName="bg-neutral-300 text-black border-2 border-accent-red rounded-md"
            />
            <CircleFilterButton
              selected={showGameworldTasks}
              onClick={toggleShowGameworldTasks}
              srLabel="Gameworld tasks"
              disabled={!showGameworldTasks}
              icon={
                <TaskSubmissionIcon
                  submissionType="gameworld"
                  size="md"
                  disabled={!showGameworldTasks}
                />
              }
              className="w-12"
              tooltip="MonQuest Task"
              tooltipClassName="bg-neutral-300 text-black border-2 border-accent-yellow rounded-md"
            />
            <CircleFilterButton
              selected={showEventTasks}
              onClick={toggleShowEventTasks}
              srLabel="Event tasks"
              disabled={!showEventTasks}
              icon={
                <TaskSubmissionIcon
                  submissionType="event"
                  size="md"
                  disabled={!showEventTasks}
                />
              }
              className="w-12"
              tooltip="Event task"
              tooltipClassName="bg-neutral-300 text-black border-2 border-accent-green rounded-md"
            />
          </div>
        </div>

        {/* Content */}
        {filteredState.length > 0 ? (
          filteredState.map((round, i) => (
            <ResearchTasksRound
              key={round.slug}
              round={round}
              index={i}
              getStyle={() => getStyle(i)}
              state={state}
              allTasksVisible={allTasksVisible}
              search={search}
              teamState={teamState}
            />
          ))
        ) : (
          <span className="text-2xl mx-auto font-bold">No results found</span>
        )}
      </div>
    </TeamStateProvider>
  );
}
