import { type TeamHuntState } from "@hunt/public-client";
import React, { useMemo } from "react";
import { hydrateRoot } from "react-dom/client";
import ResearchTasksList from "../components/ResearchTasksList";
import {
  applySolvedMapToResearchTasksState,
  useSolvedPuzzlesState,
} from "../components/puzzleSolveLocalState";
import { IS_STATIC_SITE } from "../utils/staticSite";
import { ErrataDataProvider } from "./ErrataProvider";
import { type ResearchTasksState } from "./research_tasks_types";
import useDataset from "./useDataset";

const ResearchTasksManager = ({
  initialState,
  initialTeamState,
}: {
  initialState: ResearchTasksState;
  initialTeamState: TeamHuntState;
}) => {
  const state = useDataset("research_tasks", undefined, initialState);
  const teamState = useDataset("team_state", undefined, initialTeamState);
  const { solvedMap } = useSolvedPuzzlesState();
  const mergedState = useMemo(() => {
    if (!IS_STATIC_SITE) return state;
    return applySolvedMapToResearchTasksState(state, solvedMap);
  }, [solvedMap, state]);

  return (
    <ErrataDataProvider initialTeamState={initialTeamState}>
      <ResearchTasksList state={mergedState} teamState={teamState} />
    </ErrataDataProvider>
  );
};

const researchTasksElem = document.getElementById("research-tasks-root");
if (researchTasksElem) {
  const initialResearchTasksState = (
    window as unknown as { initialResearchTasksState: ResearchTasksState }
  ).initialResearchTasksState;
  const teamState = (window as unknown as { initialTeamState: TeamHuntState })
    .initialTeamState;
  hydrateRoot(
    researchTasksElem,
    <ResearchTasksManager
      initialState={initialResearchTasksState}
      initialTeamState={teamState}
    />,
  );
} else {
  console.error(
    "Couldn't mount ResearchTasksManager because #research-tasks-root was nowhere to be found",
  );
}
